-- M13 系统对接增强：Webhook 主动回调（游标 outbox，崩溃安全）+ AppKey 签名 v2（body 纳签）。

-- ===== Webhook 订阅 =====
create table if not exists "wcs_webhook" (
    "id" bigint generated by default as identity primary key,
    "name" varchar(128) not null,
    "url" varchar(1024) not null,
    "secret" varchar(256) not null default '',            -- HMAC 密钥；订阅方据此验签回调
    "event_types" text not null default '[]',             -- JSON 数组：task.completed/task.failed/chain.completed/alarm.raised…
    "scope_app_ids" text not null default '[]',           -- JSON 数组：为空=全部设备；否则仅这些 app 的事件
    "enabled" boolean not null default true,
    "remark" varchar(1024) not null default '',
    "creator" varchar(512) not null default '',
    "create_time" timestamp(6) not null default current_timestamp,
    "last_update_time" timestamp(6) not null default current_timestamp,
    "is_valid" boolean not null default true,
    "tenant_id" bigint not null default 1
);

-- 每 webhook × 每事件源 独立游标（keyset：watermark_time + last_id）。崩溃安全：只推进到已处理的最后一行。
-- watermark_time 用 timestamp(6) 全精度（非毫秒截断）——避免亚毫秒行被反复重扫；配合扫描器的滞后窗口
-- （只处理 lut <= now()-lag 的行）防「事务先取 now 后延迟提交」的低 lut 行越过游标被永久跳过（事件丢失）。
create table if not exists "wcs_webhook_cursor" (
    "id" bigint generated by default as identity primary key,
    "webhook_id" bigint not null,
    "source" varchar(32) not null,                        -- task / alarm / chain
    "watermark_time" timestamp(6) not null default timestamp '1970-01-01 00:00:00',
    "last_id" bigint not null default 0,
    "last_update_time" timestamp(6) not null default current_timestamp,
    "tenant_id" bigint not null default 1
);
create unique index if not exists "uk_wcs_webhook_cursor" on "wcs_webhook_cursor" ("webhook_id", "source", "tenant_id");

-- keyset 扫描键索引（每源 (last_update_time,id) 排序 top-N）：任务/报警/链表增长后避免全表排序（对抗审查 P3）
create index if not exists "idx_wcs_task_lut" on "wcs_task" ("last_update_time", "id");
create index if not exists "idx_wcs_alarm_lut" on "wcs_alarm" ("last_update_time", "id");
create index if not exists "idx_wcs_task_chain_lut" on "wcs_task_chain" ("last_update_time", "id");

-- 投递记录：一行一个 (webhook,event_type,biz_id)，attempts 计数 + 退避重投。唯一键幂等去重（游标重扫/并发扫描兜底）。
create table if not exists "wcs_webhook_delivery" (
    "id" bigint generated by default as identity primary key,
    "webhook_id" bigint not null,
    "event_type" varchar(64) not null,
    "biz_id" bigint not null,                             -- task/chain/alarm 的行 id
    "payload" text not null default '{}',
    "status" varchar(16) not null default 'pending',      -- pending / ok / failed
    "attempts" bigint not null default 0,
    "next_retry_time" timestamp(6) not null default current_timestamp,
    "last_response" varchar(512) not null default '',
    "creator" varchar(512) not null default '',
    "create_time" timestamp(6) not null default current_timestamp,
    "last_update_time" timestamp(6) not null default current_timestamp,
    "is_valid" boolean not null default true,
    "tenant_id" bigint not null default 1
);
create unique index if not exists "uk_wcs_webhook_delivery" on "wcs_webhook_delivery" ("webhook_id", "event_type", "biz_id", "tenant_id");
create index if not exists "idx_wcs_webhook_delivery_due" on "wcs_webhook_delivery" ("status", "next_retry_time");

-- ===== AppKey 签名 v2：按应用可强制最低签名版本（灰度共存；2=要求 body 纳签）=====
alter table "wcs_application" add column if not exists "min_sign_version" bigint not null default 1;
